"""Weekly picks generated by the scheduler (FR-1220). Read-only."""

from __future__ import annotations

from datetime import date
from typing import Any
from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query

from app.api.deps import Ctx, get_ctx

router = APIRouter()


@router.get("")
async def list_picks(
    week_of: date | None = Query(default=None, description="Monday of the week; default latest"),
    limit: int = Query(default=20, ge=1, le=50),
    ctx: Ctx = Depends(get_ctx),
) -> dict[str, Any]:
    """The week's picks, best confidence first. Empty until the weekly job has run."""
    picks, week = await ctx.repo.list_picks(week_of=week_of, limit=limit)
    return {"success": True, "data": picks, "week_of": week}


@router.get("/{pick_id}")
async def get_pick(pick_id: UUID, ctx: Ctx = Depends(get_ctx)) -> dict[str, Any]:
    try:
        return {"success": True, "data": await ctx.repo.get_pick(pick_id)}
    except KeyError as exc:
        raise HTTPException(status_code=404, detail="Pick not found") from exc
